contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint fund, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund) + (amount)); require(fund <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= fund);
        require(fund > 0);
        require(amount > 0);
        require(amount < fund);

        // Fund c via owner-only Command sending Ether to c itself.
        c.Command{value: fund}(address(c), ""); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        require(balBefore == fund);

        // amount < balance: the if-branch is skipped, no transfer occurs.
        c.multiplicate{value: amount}(address(this)); if (__ESBMC_reverted()) return;

        assert(address(c).balance == balBefore + amount);
    }

    receive() external payable {}
}

