// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 fund, uint256 amount) internal {
        fund = bound(fund, 0, 1000000000000000000000000000000);
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        vm.assume(fund > 0);
        vm.assume(amount > 0);
        vm.assume(amount < fund);
        try c.Command{value: fund}(address(c), "") {} catch { return; }
        uint balBefore = address(c).balance;
        fund = balBefore;
        try c.multiplicate{value: amount}(address(this)) {} catch { return; }
        assertTrue(address(c).balance == balBefore + amount);
    }

    function testFuzz_run(uint256 fund, uint256 amount) public {
        _run(fund, amount);
    }

    receive() external payable {}
}
